import{_ as e,o as a,c as r,a5 as l}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"MySQL 概览","description":"MySQL 是由 Oracle 维护的开源关系型数据库管理系统。对后端开发者而言，最有价值的入口不是功能清单，而是理解一条 SQL 如何进入服务层、如何由 InnoDB 执行，以及日志、索引和事务如何共同决定性能与一致性。","frontmatter":{},"headers":[],"relativePath":"mysql/01-basics/chapter-01-overview.md","filePath":"mysql/01-basics/chapter-01-overview.md"}'),i={name:"mysql/01-basics/chapter-01-overview.md"};function s(c,t,d,n,h,o){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="mysql-概览" tabindex="-1" data-src-line="1" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 概览 <a class="header-anchor" href="#mysql-概览" aria-label="Permalink to &quot;MySQL 概览&quot;">​</a></h1><p data-src-line="3" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 是由 Oracle 维护的开源关系型数据库管理系统。对后端开发者而言，最有价值的入口不是功能清单，而是理解一条 SQL 如何进入服务层、如何由 InnoDB 执行，以及日志、索引和事务如何共同决定性能与一致性。</p><h2 id="核心组成" tabindex="-1" data-src-line="5" data-src-file="mysql/01-basics/chapter-01-overview.md">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to &quot;核心组成&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="mysql/01-basics/chapter-01-overview.md"><tr data-src-line="7" data-src-file="mysql/01-basics/chapter-01-overview.md"><th style="text-align:left;">组成</th><th style="text-align:left;">解决的问题</th><th style="text-align:left;">继续阅读</th></tr></thead><tbody data-src-line="9" data-src-file="mysql/01-basics/chapter-01-overview.md"><tr data-src-line="9" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">连接层与服务层</td><td style="text-align:left;">接收请求、解析 SQL、生成执行计划</td><td style="text-align:left;"><a href="./chapter-02-architecture.html">整体架构</a></td></tr><tr data-src-line="10" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">InnoDB 存储引擎</td><td style="text-align:left;">组织数据页、缓存、崩溃恢复和并发事务</td><td style="text-align:left;"><a href="./../02-storage-and-logging/chapter-01-data-page.html">存储与日志</a></td></tr><tr data-src-line="11" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">索引与优化器</td><td style="text-align:left;">缩小候选行范围并选择代价较低的执行方式</td><td style="text-align:left;"><a href="./../03-index/chapter-01-btree-index.html">B+ 树索引</a></td></tr><tr data-src-line="12" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">事务、MVCC 与锁</td><td style="text-align:left;">保证并发事务的隔离，并协调读写冲突</td><td style="text-align:left;"><a href="./../05-transaction-lock/chapter-01-overview.html">事务与锁</a></td></tr><tr data-src-line="13" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">复制与日志</td><td style="text-align:left;">同步变更、恢复数据并支持故障切换</td><td style="text-align:left;"><a href="./../07-replication-and-architecture/chapter-01-binlog-replication.html">复制与扩展架构</a></td></tr></tbody></table><p data-src-line="15" data-src-file="mysql/01-basics/chapter-01-overview.md">InnoDB 是 MySQL 的默认存储引擎，也是本专项的主要讨论对象。它通过 Buffer Pool 降低磁盘访问，通过 Redo Log 保证崩溃恢复，通过 Undo Log 和 Read View 支持 MVCC，通过索引与锁协调并发读写。</p><h2 id="适用场景" tabindex="-1" data-src-line="17" data-src-file="mysql/01-basics/chapter-01-overview.md">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p data-src-line="19" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 适合以在线事务处理为主、读写并发较高、能通过主从复制扩展读能力的业务。遇到复杂分析、跨地域强一致多写或单机容量上限时，需要重新评估数据模型、数据库产品和架构，而不是只增加参数。</p><p data-src-line="21" data-src-file="mysql/01-basics/chapter-01-overview.md">选版本、比较 MariaDB，或决定使用云 RDS 还是自建时，见<a href="./../10-practice/chapter-01-version-and-selection.html">版本、产品与部署选型</a>。</p><h2 id="继续阅读" tabindex="-1" data-src-line="23" data-src-file="mysql/01-basics/chapter-01-overview.md">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h2><ul data-src-line="25" data-src-file="mysql/01-basics/chapter-01-overview.md"><li data-src-line="25" data-src-file="mysql/01-basics/chapter-01-overview.md">想知道一条 SQL 如何执行：阅读<a href="./chapter-02-architecture.html">整体架构</a>。</li><li data-src-line="26" data-src-file="mysql/01-basics/chapter-01-overview.md">遇到中文、emoji 或排序比较问题：阅读<a href="./chapter-03-charset-collation.html">字符集与排序规则</a>。</li><li data-src-line="27" data-src-file="mysql/01-basics/chapter-01-overview.md">想从任务入口开始：返回<a href="./../">MySQL 专项首页</a>。</li></ul>',10)])])}const p=e(i,[["render",s]]);export{f as __pageData,p as default};
